```apex
public with sharing class ContactTriggerHandler {

    /**
     * BEFORE INSERT / UPDATE
     * Fills MailingCountry from the Account's BillingCountry when blank.
     * On insert, fills LeadSource from the Account's AccountSource when blank.
     * Uses a single SOQL query for all referenced accounts.
     */
    public void handleBefore(List<Contact> contacts, Boolean isInsert) {
        // Collect the account ids we actually need.
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        // Single SOQL query for all accounts.
        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, BillingCountry, AccountSource
             FROM Account
             WHERE Id IN :accountIds]
        );

        for (Contact c : contacts) {
            if (c.AccountId == null) {
                continue;
            }
            Account a = accountsById.get(c.AccountId);
            if (a == null) {
                continue;
            }

            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    /**
     * AFTER INSERT
     * When a new contact has a phone and its account has none, the first such
     * contact (in trigger order) per account sets the account's phone.
     * Uses a single SOQL query and a single DML statement.
     */
    public void handleAfterInsert(List<Contact> contacts) {
        // Collect account ids for contacts that have a phone.
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        // Single SOQL query for the candidate accounts.
        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, Phone
             FROM Account
             WHERE Id IN :accountIds]
        );

        // Build the accounts to update. Only the first contact (in trigger
        // order) per account whose account has no phone sets the phone.
        Map<Id, Account> accountsToUpdate = new Map<Id, Account>();
        for (Contact c : contacts) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }

            Account a = accountsById.get(c.AccountId);
            if (a == null) {
                continue;
            }

            // Account already had a phone -> nothing to do (matches original).
            if (String.isNotBlank(a.Phone)) {
                continue;
            }

            // Account started blank and we've already queued it from an earlier
            // contact -> skip, preserving "first contact wins" behaviour.
            if (accountsToUpdate.containsKey(a.Id)) {
                continue;
            }

            a.Phone = c.Phone;
            accountsToUpdate.put(a.Id, a);
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate.values();
        }
    }
}
