```apex
public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // Validate maxRows
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }

        // Validate object name
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object API name is required.');
        }

        Schema.SObjectType sObjType = Schema.getGlobalDescribe().get(objectApiName.toLowerCase());
        if (sObjType == null) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }

        Schema.DescribeSObjectResult objDescribe = sObjType.getDescribe();

        // Check object read access
        if (!objDescribe.isAccessible()) {
            throw new SearchException('You do not have read access to object: ' + objDescribe.getName());
        }

        // Build case-insensitive map of field API name -> describe
        Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();
        Map<String, Schema.DescribeFieldResult> lowerFieldMap = new Map<String, Schema.DescribeFieldResult>();
        for (String key : fieldMap.keySet()) {
            Schema.DescribeFieldResult dfr = fieldMap.get(key).getDescribe();
            lowerFieldMap.put(dfr.getName().toLowerCase(), dfr);
        }

        // Validate fields list
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be requested.');
        }

        // Build SELECT clause (always include Id first)
        List<String> selectFields = new List<String>{ 'Id' };
        for (String f : fields) {
            if (String.isBlank(f)) {
                throw new SearchException('Field name cannot be blank.');
            }
            Schema.DescribeFieldResult dfr = lowerFieldMap.get(f.toLowerCase());
            if (dfr == null) {
                throw new SearchException('Unknown field: ' + f);
            }
            if (!dfr.isAccessible()) {
                throw new SearchException('You do not have read access to field: ' + dfr.getName());
            }
            selectFields.add(dfr.getName());
        }

        // Build WHERE clause
        List<String> whereClauses = new List<String>();
        List<Object> bindValues = new List<Object>();
        Map<String, Object> bindMap = new Map<String, Object>();
        Integer bindIndex = 0;

        if (filters != null && !filters.isEmpty()) {
            for (String filterKey : filters.keySet()) {
                if (String.isBlank(filterKey)) {
                    throw new SearchException('Filter field name cannot be blank.');
                }
                Schema.DescribeFieldResult dfr = lowerFieldMap.get(filterKey.toLowerCase());
                if (dfr == null) {
                    throw new SearchException('Unknown filter field: ' + filterKey);
                }
                if (!dfr.isAccessible()) {
                    throw new SearchException('You do not have read access to filter field: ' + dfr.getName());
                }
                if (!dfr.isFilterable()) {
                    throw new SearchException('Field cannot be filtered: ' + dfr.getName());
                }
                String bindName = 'bind' + bindIndex;
                bindIndex++;
                bindMap.put(bindName, filters.get(filterKey));
                whereClauses.add(dfr.getName() + ' = :' + bindName);
            }
        }

        // Validate order by
        String orderByClause = '';
        if (!String.isBlank(orderByField)) {
            Schema.DescribeFieldResult dfr = lowerFieldMap.get(orderByField.toLowerCase());
            if (dfr == null) {
                throw new SearchException('Unknown order-by field: ' + orderByField);
            }
            if (!dfr.isAccessible()) {
                throw new SearchException('You do not have read access to order-by field: ' + dfr.getName());
            }
            if (!dfr.isSortable()) {
                throw new SearchException('Field cannot be sorted: ' + dfr.getName());
            }
            orderByClause = ' ORDER BY ' + dfr.getName() + ' ASC';
        }

        // Assemble query
        String query = 'SELECT ' + String.join(selectFields, ', ')
            + ' FROM ' + objDescribe.getName();

        if (!whereClauses.isEmpty()) {
            query += ' WHERE ' + String.join(whereClauses, ' AND ');
        }

        query += orderByClause;
        query += ' LIMIT ' + maxRows;

        try {
            return Database.queryWithBinds(query, bindMap, AccessLevel.USER_MODE);
        } catch (System.NoAccessException e) {
            throw new SearchException(e.getMessage());
        } catch (System.QueryException e) {
            throw new SearchException(e.getMessage());
        } catch (System.TypeException e) {
            throw new SearchException(e.getMessage());
        } catch (System.SObjectException e) {
            throw new SearchException(e.getMessage());
        }
    }
}
