```apex
public with sharing class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public static OrderPayloadParser.Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Body is null or blank.');
        }

        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Body is not valid JSON.');
        }

        if (!(parsed instanceof Map<String, Object>)) {
            throw new PayloadException('Body is not a JSON object.');
        }

        Map<String, Object> root = (Map<String, Object>) parsed;

        Order order = new Order();

        // number (required, non-blank)
        Object numberVal = root.get('number');
        String orderNumber = numberVal == null ? null : String.valueOf(numberVal);
        if (String.isBlank(orderNumber)) {
            throw new PayloadException('Missing or blank "number".');
        }
        order.orderNumber = orderNumber;

        // date
        Object dateVal = root.get('date');
        if (dateVal != null && !String.isBlank(String.valueOf(dateVal))) {
            try {
                order.orderDate = Date.valueOf(String.valueOf(dateVal));
            } catch (Exception e) {
                throw new PayloadException('Invalid "date" format.');
            }
        }

        // currency
        Object currencyVal = root.get('currency');
        if (currencyVal != null) {
            order.currencyCode = String.valueOf(currencyVal);
        }

        // customer.email
        Object customerVal = root.get('customer');
        if (customerVal != null) {
            if (!(customerVal instanceof Map<String, Object>)) {
                throw new PayloadException('"customer" is not a JSON object.');
            }
            Map<String, Object> customer = (Map<String, Object>) customerVal;
            Object emailVal = customer.get('email');
            if (emailVal != null) {
                order.customerEmail = String.valueOf(emailVal);
            }
        }

        // lines
        List<Line> lines = new List<Line>();
        Object linesVal = root.get('lines');
        if (linesVal != null) {
            if (!(linesVal instanceof List<Object>)) {
                throw new PayloadException('"lines" is not a JSON array.');
            }
            for (Object lineObj : (List<Object>) linesVal) {
                if (!(lineObj instanceof Map<String, Object>)) {
                    throw new PayloadException('A line is not a JSON object.');
                }
                lines.add(parseLine((Map<String, Object>) lineObj));
            }
        }
        order.lines = lines;

        // total
        Decimal total = 0;
        for (Line l : lines) {
            total += l.lineTotal;
        }
        order.total = total;

        return order;
    }

    private static Line parseLine(Map<String, Object> lineMap) {
        Line line = new Line();

        // sku (required)
        Object skuVal = lineMap.get('sku');
        if (skuVal == null || String.isBlank(String.valueOf(skuVal))) {
            throw new PayloadException('Line missing "sku".');
        }
        line.sku = String.valueOf(skuVal);

        // quantity (required, positive integer)
        Object qtyVal = lineMap.get('quantity');
        if (qtyVal == null) {
            throw new PayloadException('Line missing "quantity".');
        }
        Integer quantity;
        try {
            Decimal qDec = toDecimal(qtyVal);
            if (qDec.scale() > 0 && qDec != qDec.setScale(0)) {
                throw new PayloadException('Line "quantity" is not an integer.');
            }
            quantity = qDec.intValue();
        } catch (PayloadException pe) {
            throw pe;
        } catch (Exception e) {
            throw new PayloadException('Line "quantity" is invalid.');
        }
        if (quantity <= 0) {
            throw new PayloadException('Line "quantity" is not positive.');
        }
        line.quantity = quantity;

        // unitPrice (required, non-negative)
        Object priceVal = lineMap.get('unitPrice');
        if (priceVal == null) {
            throw new PayloadException('Line missing "unitPrice".');
        }
        Decimal unitPrice;
        try {
            unitPrice = toDecimal(priceVal);
        } catch (Exception e) {
            throw new PayloadException('Line "unitPrice" is invalid.');
        }
        if (unitPrice < 0) {
            throw new PayloadException('Line "unitPrice" is negative.');
        }
        line.unitPrice = unitPrice;

        // discount (optional, default 0)
        Object discountVal = lineMap.get('discount');
        Decimal discount = 0;
        if (discountVal != null) {
            try {
                discount = toDecimal(discountVal);
            } catch (Exception e) {
                throw new PayloadException('Line "discount" is invalid.');
            }
        }
        line.discount = discount;

        // lineTotal = quantity * unitPrice * (1 - discount), rounded half up to 2 dp
        Decimal raw = (Decimal) quantity * unitPrice * (1 - discount);
        line.lineTotal = raw.setScale(2, System.RoundingMode.HALF_UP);

        return line;
    }

    private static Decimal toDecimal(Object val) {
        if (val instanceof Decimal) {
            return (Decimal) val;
        }
        if (val instanceof Integer) {
            return (Decimal) ((Integer) val);
        }
        if (val instanceof Long) {
            return (Decimal) ((Long) val);
        }
        if (val instanceof Double) {
            return Decimal.valueOf((Double) val);
        }
        if (val instanceof String) {
            return Decimal.valueOf((String) val);
        }
        throw new PayloadException('Value is not numeric.');
    }

    public static String toAcknowledgement(OrderPayloadParser.Order order) {
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', order.lines == null ? 0 : order.lines.size());
        ack.put('total', order.total);
        return JSON.serialize(ack);
    }
}
