public with sharing class LeadImportService {

    public class ImportResult {
        public Integer successCount;
        public List<Id> insertedIds;
        public Map<Integer, String> errorsByIndex;

        public ImportResult() {
            this.successCount = 0;
            this.insertedIds = new List<Id>();
            this.errorsByIndex = new Map<Integer, String>();
        }
    }

    public static LeadImportService.ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();

        if (leads == null || leads.isEmpty()) {
            return result;
        }

        // Track which original indexes are candidates for insertion, and
        // which are duplicates to be rejected without DML.
        Set<String> seenEmails = new Set<String>();

        // Maps position in the DML list back to the original input index.
        List<Lead> toInsert = new List<Lead>();
        List<Integer> dmlIndexToInput = new List<Integer>();

        for (Integer i = 0; i < leads.size(); i++) {
            Lead ld = leads[i];

            if (ld == null) {
                // Treat a null lead as a database rejection-style error.
                result.errorsByIndex.put(i, 'Lead is null');
                continue;
            }

            String rawEmail = ld.Email;
            String normalizedEmail = null;
            if (rawEmail != null) {
                String trimmed = rawEmail.trim();
                if (trimmed.length() > 0) {
                    normalizedEmail = trimmed.toLowerCase();
                }
            }

            if (normalizedEmail != null) {
                if (seenEmails.contains(normalizedEmail)) {
                    result.errorsByIndex.put(i, 'Duplicate email in import: ' + normalizedEmail);
                    continue;
                }
                seenEmails.add(normalizedEmail);
            }

            // Default LeadSource when blank.
            if (String.isBlank(ld.LeadSource)) {
                ld.LeadSource = 'Web';
            }

            toInsert.add(ld);
            dmlIndexToInput.add(i);
        }

        if (toInsert.isEmpty()) {
            return result;
        }

        Database.SaveResult[] saveResults = Database.insert(toInsert, false);

        for (Integer j = 0; j < saveResults.size(); j++) {
            Database.SaveResult sr = saveResults[j];
            Integer inputIndex = dmlIndexToInput[j];

            if (sr.isSuccess()) {
                result.successCount++;
                result.insertedIds.add(sr.getId());
            } else {
                List<String> messages = new List<String>();
                for (Database.Error err : sr.getErrors()) {
                    messages.add(err.getMessage());
                }
                result.errorsByIndex.put(inputIndex, String.join(messages, '; '));
            }
        }

        return result;
    }
}
