public with sharing class PicklistService {

    public class PicklistServiceException extends Exception {}

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException('Object API name must not be null or blank.');
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Field API name must not be null or blank.');
        }

        Schema.DescribeSObjectResult objDescribe = describeObject(objectApiName.trim());
        Schema.DescribeFieldResult fieldDescribe = describeField(objDescribe, fieldApiName.trim());

        Schema.DisplayType type = fieldDescribe.getType();
        if (type != Schema.DisplayType.Picklist && type != Schema.DisplayType.MultiPicklist) {
            throw new PicklistServiceException(
                'Field ' + fieldApiName + ' on ' + objectApiName + ' is not a picklist or multi-select picklist field.');
        }

        List<Option> result = new List<Option>();
        for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
            if (entry.isActive()) {
                result.add(new Option(entry.getValue(), entry.getLabel(), entry.isDefaultValue()));
            }
        }
        return result;
    }

    private static Schema.DescribeSObjectResult describeObject(String objectApiName) {
        Schema.SObjectType sobjType = Schema.getGlobalDescribe().get(objectApiName.toLowerCase());
        if (sobjType == null) {
            throw new PicklistServiceException('Object does not exist: ' + objectApiName);
        }
        return sobjType.getDescribe();
    }

    private static Schema.DescribeFieldResult describeField(Schema.DescribeSObjectResult objDescribe, String fieldApiName) {
        Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();
        Schema.SObjectField field = fieldMap.get(fieldApiName.toLowerCase());
        if (field == null) {
            throw new PicklistServiceException(
                'Field does not exist: ' + fieldApiName + ' on ' + objDescribe.getName());
        }
        return field.getDescribe();
    }
}
