@IsTest
private class RenewalServiceTest {
    @IsTest
    static void createRenewals_registersRenewalAndTaskForClosedWon() {
        // Given
        fflib_ApexMocks mocks = new fflib_ApexMocks();

        IOpportunitiesSelector selectorMock =
            (IOpportunitiesSelector) mocks.mock(OpportunitiesSelector.class);
        fflib_ISObjectUnitOfWork uowMock =
            (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);

        Id oppId = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Id accountId = fflib_IDGenerator.generate(Account.SObjectType);
        Id ownerId = fflib_IDGenerator.generate(User.SObjectType);

        Date closeDate = Date.newInstance(2024, 3, 15);
        Opportunity won = new Opportunity(
            Id = oppId,
            Name = 'Big Deal',
            AccountId = accountId,
            OwnerId = ownerId,
            StageName = 'Closed Won',
            CloseDate = closeDate,
            Amount = 1000
        );

        Set<Id> ids = new Set<Id>{ oppId };

        mocks.startStubbing();
        mocks.when(selectorMock.sObjectType()).thenReturn(Opportunity.SObjectType);
        mocks.when(selectorMock.selectById(ids)).thenReturn(new List<Opportunity>{ won });
        mocks.stopStubbing();

        Application.Selector.setMock(selectorMock);
        Application.UnitOfWork.setMock(uowMock);

        // When
        Test.startTest();
        RenewalService.createRenewals(ids);
        Test.stopTest();

        // Then - capture the renewal passed to registerNew(SObject)
        fflib_ArgumentCaptor renewalCaptor = fflib_ArgumentCaptor.forClass(Opportunity.class);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1))
            .registerNew((SObject) renewalCaptor.capture());

        Opportunity renewal = (Opportunity) renewalCaptor.getValue();
        System.assertEquals('Big Deal - Renewal', renewal.Name, 'Renewal name');
        System.assertEquals(accountId, renewal.AccountId, 'Renewal account');
        System.assertEquals('Prospecting', renewal.StageName, 'Renewal stage');
        System.assertEquals(closeDate.addYears(1), renewal.CloseDate, 'Renewal close date');
        System.assertEquals(
            (1000 * RenewalService.UPLIFT).setScale(2),
            renewal.Amount,
            'Renewal amount uplifted and scaled'
        );

        // Then - capture the task registered as a child of the renewal
        fflib_ArgumentCaptor taskCaptor = fflib_ArgumentCaptor.forClass(Task.class);
        fflib_ArgumentCaptor relToCaptor = fflib_ArgumentCaptor.forClass(Schema.SObjectField.class);
        fflib_ArgumentCaptor parentCaptor = fflib_ArgumentCaptor.forClass(Opportunity.class);

        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).registerNew(
            (SObject) taskCaptor.capture(),
            (Schema.SObjectField) relToCaptor.capture(),
            (SObject) parentCaptor.capture()
        );

        Task reminder = (Task) taskCaptor.getValue();
        System.assertEquals('Prepare renewal for Big Deal', reminder.Subject, 'Task subject');
        System.assertEquals(ownerId, reminder.OwnerId, 'Task owner is original opp owner');
        System.assertEquals(
            renewal.CloseDate.addDays(-60),
            reminder.ActivityDate,
            'Task activity date is renewal close date minus 60 days'
        );

        System.assertEquals(
            Task.WhatId,
            (Schema.SObjectField) relToCaptor.getValue(),
            'Task related via WhatId'
        );

        Opportunity parent = (Opportunity) parentCaptor.getValue();
        System.assert(
            parent === renewal,
            'Task parent must be the new renewal, not the original opportunity'
        );

        // commitWork called exactly once
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).commitWork();
    }

