            // Publish only after the DML transaction has committed successfully.
            uow.registerPublishAfterSuccessTransaction(new Deal_Won__e(
                Opportunity_Id__c = opp.Id,
                Amount__c = opp.Amount
            ));

            closedCount++;
        }

        uow.commitWork();

        return closedCount;
    }
