public with sharing class AccountRatingService {

    private static final Decimal HOT_THRESHOLD = 100000;

    @future
    public static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Track the best open-opportunity state per account.
        Map<Id, Boolean> hasOpenByAccount = new Map<Id, Boolean>();
        Map<Id, Boolean> hasHotByAccount = new Map<Id, Boolean>();

        // Initialise so accounts with no open opportunities get "Cold".
        for (Id accountId : accountIds) {
            hasOpenByAccount.put(accountId, false);
            hasHotByAccount.put(accountId, false);
        }

        for (Opportunity opp : [
            SELECT Id, AccountId, Amount
            FROM Opportunity
            WHERE AccountId IN :accountIds
            AND IsClosed = false
        ]) {
            hasOpenByAccount.put(opp.AccountId, true);
            if (opp.Amount != null && opp.Amount >= HOT_THRESHOLD) {
                hasHotByAccount.put(opp.AccountId, true);
            }
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            String rating;
            if (hasHotByAccount.get(accountId)) {
                rating = 'Hot';
            } else if (hasOpenByAccount.get(accountId)) {
                rating = 'Warm';
            } else {
                rating = 'Cold';
            }

            accountsToUpdate.add(new Account(
                Id = accountId,
                Rating = rating
            ));
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
```

