public with sharing class LineItemDiscountHandler {

    /**
     * For each new line whose Discount is null, set it to the standard
     * discount for its product. Lines with an existing Discount (including 0)
     * are left untouched.
     *
     * Rule logic stays in PricingRules (via standardDiscountForFamily); this
     * handler only bulkifies the data access so a 200-line CPQ insert stays
     * within governor limits (one query instead of one per line).
     */
    public static void applyStandardDiscounts(List<OpportunityLineItem> newLines) {
        // Collect product Ids only for lines that actually need a discount.
        Set<Id> productIds = new Set<Id>();
        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null && line.Product2Id != null) {
                productIds.add(line.Product2Id);
            }
        }

        if (productIds.isEmpty()) {
            return;
        }

        // Single query for all needed products.
        Map<Id, Product2> productsById = new Map<Id, Product2>(
            [SELECT Id, Family FROM Product2 WHERE Id IN :productIds]
        );

        for (OpportunityLineItem line : newLines) {
            if (line.Discount != null || line.Product2Id == null) {
                continue;
            }
            Product2 product = productsById.get(line.Product2Id);
            String family = (product == null) ? null : product.Family;
            // Rules themselves remain owned by PricingRules.
            line.Discount = PricingRules.standardDiscountForFamily(family);
        }
    }
}
