```javascript
import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY = 300;
const MIN_CHARS = 2;

export default class ContactSearch extends LightningElement {
    contacts = [];
    error;

    _debounceTimer;
    _latestRequestId = 0;
    _isConnected = true;

    disconnectedCallback() {
        this._isConnected = false;
        clearTimeout(this._debounceTimer);
    }

    handleChange(event) {
        const searchTerm = (event.target.value || '').trim();

        // Cancel any pending search
        clearTimeout(this._debounceTimer);

        if (searchTerm.length < MIN_CHARS) {
            // Invalidate any in-flight responses and clear results
            this._latestRequestId++;
            this.contacts = [];
            this.error = undefined;
            return;
        }

        this._debounceTimer = setTimeout(() => {
            this.performSearch(searchTerm);
        }, DEBOUNCE_DELAY);
    }

    performSearch(searchTerm) {
        if (!this._isConnected) {
            return;
        }

        const requestId = ++this._latestRequestId;

        searchContacts({ searchTerm })
            .then((result) => {
                // Ignore stale responses and ignore if removed from page
                if (!this._isConnected || requestId !== this._latestRequestId) {
                    return;
                }
                this.contacts = result;
                this.error = undefined;
            })
            .catch((error) => {
                if (!this._isConnected || requestId !== this._latestRequestId) {
                    return;
                }
                this.contacts = [];
                this.error = error;
            });
    }
}
