import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL = 60000;

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    error;

    _intervalId = null;
    _inFlight = false;
    _hasStats = false;

    // Bound handler so we can add/remove the same reference.
    _visibilityHandler = this.handleVisibilityChange.bind(this);

    connectedCallback() {
        document.addEventListener('visibilitychange', this._visibilityHandler);
        // Only start if the page is currently visible.
        if (document.visibilityState !== 'hidden') {
            this.startPolling();
        }
    }

    disconnectedCallback() {
        document.removeEventListener('visibilitychange', this._visibilityHandler);
        this.stopPolling();
        this._inFlight = false;
    }

    handleVisibilityChange() {
        if (document.visibilityState === 'hidden') {
            this.stopPolling();
        } else {
            // Became visible: load immediately and resume the 60s loop.
            this.startPolling();
        }
    }

    startPolling() {
        // Ensure only one polling loop exists at a time.
        this.stopPolling();
        // Immediate load.
        this.loadStats();
        this._intervalId = setInterval(() => {
            this.loadStats();
        }, REFRESH_INTERVAL);
    }

    stopPolling() {
        if (this._intervalId !== null) {
            clearInterval(this._intervalId);
            this._intervalId = null;
        }
    }

    loadStats() {
        // Skip if the page is hidden.
        if (document.visibilityState === 'hidden') {
            return;
        }
        // Skip if a request is already in flight.
        if (this._inFlight) {
            return;
        }
        this._inFlight = true;

        getQueueStats()
            .then((result) => {
                this.waiting = result.waiting;
                this.longestWaitMinutes = result.longestWaitMinutes;
                this.error = undefined;
                this._hasStats = true;
            })
            .catch((err) => {
                this.error =
                    err && err.body && err.body.message
                        ? err.body.message
                        : 'Unknown error';
            })
            .finally(() => {
                this._inFlight = false;
            });
    }

    get hasStats() {
        return this._hasStats && !this.error;
    }
}
