import { LightningElement, api, track } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _value = '';
    _activeValue = '';

    @api
    get options() {
        return this._options;
    }
    set options(val) {
        this._options = Array.isArray(val) ? val : [];
        this.initActive();
    }

    @api
    get value() {
        return this._value;
    }
    set value(val) {
        this._value = val == null ? '' : val;
        // When the parent changes value, the active option moves to it.
        if (this.hasOption(this._value)) {
            this._activeValue = this._value;
        } else {
            this.initActive();
        }
    }

    hasOption(value) {
        return this._options.some((o) => o.value === value);
    }

    initActive() {
        if (this.hasOption(this._value)) {
            this._activeValue = this._value;
        } else if (this._options.length > 0) {
            this._activeValue = this._options[0].value;
        } else {
            this._activeValue = '';
        }
    }

    optionId(value) {
        return `option-${value}`;
    }

    get activeDescendant() {
        if (this._activeValue === '' && !this.hasOption(this._activeValue)) {
            return undefined;
        }
        return this.hasOption(this._activeValue)
            ? this.optionId(this._activeValue)
            : undefined;
    }

    get computedOptions() {
        return this._options.map((o) => ({
            value: o.value,
            label: o.label,
            id: this.optionId(o.value),
            selected: o.value === this._value ? 'true' : 'false'
        }));
    }

    get activeIndex() {
        return this._options.findIndex((o) => o.value === this._activeValue);
    }

    setActiveByIndex(index) {
        if (index < 0) {
            index = 0;
        }
        if (index > this._options.length - 1) {
            index = this._options.length - 1;
        }
        if (index >= 0) {
            this._activeValue = this._options[index].value;
        }
    }

    selectValue(value) {
        if (value === this._value) {
            return;
        }
        this._value = value;
        this._activeValue = value;
        this.dispatchEvent(
            new CustomEvent('change', { detail: { value } })
        );
    }

    handleKeydown(event) {
        const key = event.key;
        const handledKeys = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

        if (!handledKeys.includes(key)) {
            return;
        }

        event.preventDefault();

        const current = this.activeIndex;

        switch (key) {
            case 'ArrowDown':
                this.setActiveByIndex(current + 1);
                break;
            case 'ArrowUp':
                this.setActiveByIndex(current - 1);
                break;
            case 'Home':
                this.setActiveByIndex(0);
                break;
            case 'End':
                this.setActiveByIndex(this._options.length - 1);
                break;
            case 'Enter':
            case ' ':
                if (this.hasOption(this._activeValue)) {
                    this.selectValue(this._activeValue);
                }
                break;
            default:
                break;
        }
    }

    handleClick(event) {
        const value = event.currentTarget.dataset.value;
        this._activeValue = value;
        this.selectValue(value);
    }
}
