```apex
/**
 * Sets the current employer (primary Affiliation) for a set of contacts.
 *
 * Relies on NPSP's standard mechanism: updating Contact.npsp__Primary_Affiliation__c
 * triggers AFFL_Affiliations_TDTM, which:
 *   - creates a Current, primary npe5__Affiliation__c to the new organization,
 *   - demotes the previous primary affiliation to Former, non-primary with EndDate = today,
 * while the contact remains in its existing household account.
 */
public with sharing class EmployerService {

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        // A null or empty map does nothing.
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // SOQL #1: read current primary affiliation for the contacts.
        List<Contact> contacts = [
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :employerByContactId.keySet()
        ];

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact c : contacts) {
            Id desiredOrgId = employerByContactId.get(c.Id);

            // Skip null target orgs.
            if (desiredOrgId == null) {
                continue;
            }

            // If the organization already is the contact's primary affiliation,
            // nothing changes (no duplicate affiliation).
            if (c.npsp__Primary_Affiliation__c == desiredOrgId) {
                continue;
            }

            // Changing the primary affiliation lookup lets NPSP do the rest.
            c.npsp__Primary_Affiliation__c = desiredOrgId;
            contactsToUpdate.add(c);
        }

        if (!contactsToUpdate.isEmpty()) {
            // DML #1: update contacts; NPSP's TDTM handler creates/updates the
            // affiliations (that TDTM work does not count against this method's
            // own DML/SOQL governor budget here).
            update contactsToUpdate;
        }
    }
}
