```apex
public with sharing class GauAllocationService {

    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(
        Id opportunityId,
        Map<Id, Decimal> percentByGauId
    ) {
        // --- Basic input validation -------------------------------------
        if (opportunityId == null) {
            throw new AllocationException('An opportunity Id is required.');
        }

        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('At least one GAU percentage must be provided.');
        }

        // --- Validate percentages ---------------------------------------
        Decimal total = 0;
        for (Id gauId : percentByGauId.keySet()) {
            Decimal pct = percentByGauId.get(gauId);
            if (pct == null || pct <= 0) {
                throw new AllocationException(
                    'Every percentage must be a value greater than 0. Invalid value for GAU ' + gauId + '.'
                );
            }
            total += pct;
        }

        if (total > 100) {
            throw new AllocationException(
                'The sum of all percentages must not exceed 100 (received ' + total + ').'
            );
        }

        // --- Validate the GAUs exist and are active ---------------------
        Map<Id, npsp__General_Accounting_Unit__c> gaus = new Map<Id, npsp__General_Accounting_Unit__c>(
            [
                SELECT Id, npsp__Active__c
                FROM npsp__General_Accounting_Unit__c
                WHERE Id IN :percentByGauId.keySet()
            ]
        );

        for (Id gauId : percentByGauId.keySet()) {
            npsp__General_Accounting_Unit__c gau = gaus.get(gauId);
            if (gau == null) {
                throw new AllocationException('General Accounting Unit ' + gauId + ' does not exist.');
            }
            if (gau.npsp__Active__c != true) {
                throw new AllocationException('General Accounting Unit ' + gauId + ' is inactive.');
            }
        }

        // --- All validation passed: now mutate data ---------------------
        // Remove existing allocations for this opportunity.
        List<npsp__Allocation__c> existing = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];
        if (!existing.isEmpty()) {
            delete existing;
        }

        // Build new percent-based allocations.
        // Intentionally only set npsp__Percent__c (not npsp__Amount__c) so that
        // NPSP recalculates the amount from the opportunity amount whenever it
        // changes later, keeping the split correct automatically.
        List<npsp__Allocation__c> toInsert = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            toInsert.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percentByGauId.get(gauId)
            ));
        }

        insert toInsert;

        return toInsert;
    }
}
