```apex
public with sharing class HouseholdService {

    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty');
        }

        // Resolve the NPSP Household Account record type Id without hard-coding.
        Schema.RecordTypeInfo hhInfo = Account.SObjectType.getDescribe()
            .getRecordTypeInfosByDeveloperName()
            .get('HH_Account');
        if (hhInfo == null) {
            throw new IllegalStateException('HH_Account record type not found on Account.');
        }
        Id hhRecordTypeId = hhInfo.getRecordTypeId();

        // Create the single household account up front with the Household record type.
        // Do NOT set the Name so that NPSP can generate the household name and greetings.
        Account household = new Account(RecordTypeId = hhRecordTypeId);
        insert household;

        // Assign every member to this household account before insert so NPSP
        // does not spin up an individual household per contact.
        for (Contact c : members) {
            c.AccountId = household.Id;
        }
        insert members;

        // Set the first contact as the household's primary contact.
        household.npe01__One2OneContact__c = members[0].Id;
        update household;

        return household.Id;
    }
}
