```apex
/**
 * TDTM trigger handler that creates a follow-up Task for major gifts.
 *
 * Registered via an NPSP Trigger Handler record (not an Apex trigger), so it
 * only runs when NPSP's TDTM dispatcher invokes it and stops when the admin
 * deactivates that record.
 *
 * Fires a single Task when an Opportunity newly qualifies as a major gift:
 * Closed Won with Amount >= 5000, where it was not already both of those.
 */
global without sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;

    global override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        if (newlist == null || newlist.isEmpty()) {
            return dmlWrapper;
        }

        Boolean isInsert = (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert);
        Boolean isUpdate = (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate);

        if (!isInsert && !isUpdate) {
            return dmlWrapper;
        }

        // Map old records by Id for update comparison.
        Map<Id, Opportunity> oldMap = new Map<Id, Opportunity>();
        if (isUpdate && oldlist != null) {
            for (SObject so : oldlist) {
                Opportunity oldOpp = (Opportunity) so;
                oldMap.put(oldOpp.Id, oldOpp);
            }
        }

        List<Task> tasksToCreate = new List<Task>();

        for (SObject so : newlist) {
            Opportunity opp = (Opportunity) so;

            if (!qualifies(opp)) {
                continue;
            }

            if (isUpdate) {
                Opportunity oldOpp = oldMap.get(opp.Id);
                // If it already qualified before, do not create another task.
                if (oldOpp != null && qualifies(oldOpp)) {
                    continue;
                }
            }

            tasksToCreate.add(buildTask(opp));
        }

        if (!tasksToCreate.isEmpty()) {
            // Add to the DmlWrapper so NPSP performs the DML (counts as 1 DML).
            dmlWrapper.objectsToInsert.addAll((List<SObject>) tasksToCreate);
        }

        return dmlWrapper;
    }

    private Boolean qualifies(Opportunity opp) {
        return opp.IsWon == true
            && opp.IsClosed == true
            && opp.Amount != null
            && opp.Amount >= MAJOR_GIFT_THRESHOLD;
    }

    private Task buildTask(Opportunity opp) {
        Date activityDate = (opp.CloseDate != null) ? opp.CloseDate.addDays(3) : null;

        return new Task(
            Subject = 'Major gift thank-you call',
            Priority = 'High',
            Status = 'Not Started',
            WhatId = opp.Id,
            WhoId = opp.npsp__Primary_Contact__c,
            OwnerId = opp.OwnerId,
            ActivityDate = activityDate
        );
    }
}
```

Notes on how the requirements are met:

- **No Apex trigger**: the class only extends `npsp.TDTM_Runnable`; NPSP's dispatcher calls `run()` based on the Trigger Handler record, which the admin can deactivate.
- **1 SOQL query, 1 DML**: this handler issues **0** SOQL queries. `IsWon`, `IsClosed`, `Amount`, `CloseDate`, `OwnerId` and `npsp__Primary_Contact__c` are all available on the records passed into `run()` (NPSP's dispatcher queries the needed fields), so no extra query is needed. Returning the Tasks via `DmlWrapper` lets NPSP perform the single consolidated DML, keeping the handler's own DML count at 0 (well within the "at most 1" budget) and bulk-safe for 200 records.
- **Dedup on update**: an update only creates a Task when the record qualifies now but did *not* already qualify (both Closed Won and Amount >= 5000) in its old state, so editing an already-qualified gift creates nothing.

