```apex
public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        Map<Id, Integer> seen = TriggerBase.idToNumberOfTimesSeenAfterUpdate;

        List<Task> tasksToInsert = new List<Task>();
        for (Integer i = 0; i < triggerNew.size(); i++) {
            Opportunity newOpp = triggerNew[i];
            Opportunity oldOpp = triggerOld[i];

            // Only act on the first after-update pass for this record in the transaction.
            // The rounding action (Order 20) re-updates the same records, triggering a
            // second after-update pass; TAF's idToNumberOfTimesSeenAfterUpdate lets us
            // ignore that re-run so we emit at most one task per opportunity per transaction.
            Integer timesSeen = seen.get(newOpp.Id);
            if (timesSeen != null && timesSeen > 1) {
                continue;
            }

            if (newOpp.Amount != oldOpp.Amount) {
                tasksToInsert.add(
                    new Task(
                        Subject = 'Amount changed',
                        WhatId = newOpp.Id,
                        Status = 'Completed'
                    )
                );
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
